import type { Metric, Point } from './data'

export type Kind = 'spike' | 'drop' | 'normal'
export type Severity = 'high' | 'medium' | 'low'

/** Above the range is a spike, below it a drop, inside it nothing */
export const kindOf = (p: Point): Kind =>
  p.actual > p.high ? 'spike' : p.actual < p.low ? 'drop' : 'normal'

/** The middle of the expected range */
export const expected = (p: Point) => (p.low + p.high) / 2

/** How far the actual is from the expected value, in percent */
export const change = (p: Point) =>
  ((p.actual - expected(p)) / expected(p)) * 100

/**
 * How far outside the range, measured in half-widths of the range: 0 is
 * inside it, 1 is as far out again as the range is from its middle.
 */
export function distance(p: Point) {
  const half = (p.high - p.low) / 2
  if (p.actual > p.high) return (p.actual - p.high) / half
  if (p.actual < p.low) return (p.low - p.actual) / half
  return 0
}

export function severity(p: Point): Severity | null {
  const d = distance(p)
  if (d === 0) return null
  return d >= 1.5 ? 'high' : d >= 0.5 ? 'medium' : 'low'
}

/** Whether the move is in the direction the metric wants */
export const isGood = (m: Metric) => {
  const kind = kindOf(m.today)
  return kind !== 'normal' && (kind === 'spike') === (m.better === 'up')
}

/** What the move means for this metric */
export const verdict = (m: Metric) =>
  `${isGood(m) ? 'Better' : 'Worse'} than usual`

export type View = 'anomalies' | 'spike' | 'drop' | 'all'

export const views: { id: View; label: string }[] = [
  { id: 'anomalies', label: 'Anomalies' },
  { id: 'spike', label: 'Spikes' },
  { id: 'drop', label: 'Drops' },
  { id: 'all', label: 'All metrics' },
]

export function inView(m: Metric, view: View) {
  const kind = kindOf(m.today)
  if (view === 'all') return true
  if (view === 'anomalies') return kind !== 'normal'
  return kind === view
}

/** The facts beside the chart in the expanded row */
export function context(m: Metric) {
  const last7 = m.history.slice(-7)
  return {
    average7: last7.reduce((s, p) => s + p.actual, 0) / last7.length,
    lastWeek: m.history[m.history.length - 7],
    outside: m.history.filter((p) => kindOf(p) !== 'normal'),
  }
}

/** A value in the metric's unit: "$48,200", "3.40%", "420 ms" */
export function formatValue(n: number, { unit }: Pick<Metric, 'unit'>) {
  switch (unit) {
    case 'currency':
      return n >= 1000
        ? `$${Math.round(n).toLocaleString('en-US')}`
        : `$${n.toFixed(2)}`
    case 'percent':
      return `${n.toFixed(n < 10 ? 2 : 1)}%`
    case 'ms':
      return n >= 1000 ? `${(n / 1000).toFixed(2)} s` : `${Math.round(n)} ms`
    default:
      return Math.round(n).toLocaleString('en-US')
  }
}

export const formatChange = (pct: number) =>
  `${pct > 0 ? '+' : pct < 0 ? '−' : ''}${Math.abs(Math.round(pct))}%`

const months = [
  'Jan',
  'Feb',
  'Mar',
  'Apr',
  'May',
  'Jun',
  'Jul',
  'Aug',
  'Sep',
  'Oct',
  'Nov',
  'Dec',
]

/** "2026-11-04" → "Nov 4", without Date, so time zones can't shift it */
export function formatDay(iso: string) {
  const [, m, d] = iso.split('-').map(Number)
  return `${months[m - 1]} ${d}`
}

import { useState } from 'react'

import { cn } from '#/lib/utils'
import { formatDay, formatValue, kindOf } from './anomalies'
import type { Metric } from './data'

const W = 560
const H = 140
const PAD = { top: 10, right: 12, bottom: 10, left: 12 }

/**
 * Fourteen days and today: the expected range as a band, what happened as a
 * line, and every day outside the band as a dot. Hovering shows a day.
 */
export function HistoryChart({ metric }: { metric: Metric }) {
  const points = [...metric.history, metric.today]
  const [hover, setHover] = useState<number | null>(null)

  const values = points.flatMap((p) => [p.actual, p.low, p.high])
  const min = Math.min(...values)
  const max = Math.max(...values)
  const pad = (max - min) * 0.08 || 1
  const x = (i: number) =>
    PAD.left + (i / (points.length - 1)) * (W - PAD.left - PAD.right)
  const y = (v: number) =>
    PAD.top +
    (1 - (v - (min - pad)) / (max - min + pad * 2)) * (H - PAD.top - PAD.bottom)

  const band = [
    ...points.map((p, i) => `${x(i)},${y(p.high)}`),
    ...points.map((p, i) => `${x(i)},${y(p.low)}`).reverse(),
  ].join(' ')
  const line = points.map((p, i) => `${x(i)},${y(p.actual)}`).join(' ')
  const shown = hover === null ? null : points[hover]

  return (
    <figure className="min-w-0 space-y-1.5">
      <div className="relative">
        <svg
          viewBox={`0 0 ${W} ${H}`}
          className="block h-auto w-full overflow-visible"
          aria-hidden
          onPointerMove={(e) => {
            const box = e.currentTarget.getBoundingClientRect()
            const at = ((e.clientX - box.left) / box.width) * W
            const i = Math.round(
              ((at - PAD.left) / (W - PAD.left - PAD.right)) *
                (points.length - 1),
            )
            setHover(Math.max(0, Math.min(points.length - 1, i)))
          }}
          onPointerLeave={() => setHover(null)}
        >
          <polygon points={band} className="fill-muted-foreground/12" />
          {hover !== null ? (
            <line
              x1={x(hover)}
              x2={x(hover)}
              y1={PAD.top}
              y2={H - PAD.bottom}
              className="stroke-muted-foreground/50"
              strokeWidth={1}
            />
          ) : null}
          <polyline
            points={line}
            fill="none"
            className="stroke-foreground"
            strokeWidth={2}
            strokeLinejoin="round"
            strokeLinecap="round"
          />
          {points.map((p, i) => {
            const kind = kindOf(p)
            const today = i === points.length - 1
            if (kind === 'normal' && !today && hover !== i) return null
            return (
              <circle
                key={p.date}
                cx={x(i)}
                cy={y(p.actual)}
                r={today ? 5 : 4}
                className={cn(
                  'stroke-background',
                  kind === 'spike'
                    ? 'fill-orange-500'
                    : kind === 'drop'
                      ? 'fill-violet-500'
                      : 'fill-foreground',
                )}
                strokeWidth={2}
              />
            )
          })}
        </svg>
        {shown && hover !== null ? (
          <div
            className="pointer-events-none absolute top-0 z-10 w-max -translate-x-1/2 rounded-md border bg-popover px-2.5 py-1.5 text-xs text-popover-foreground shadow-md"
            style={{
              left: `${Math.min(88, Math.max(12, (x(hover) / W) * 100))}%`,
            }}
          >
            <p className="text-sm font-semibold tabular-nums">
              {formatValue(shown.actual, metric)}
            </p>
            <p className="text-muted-foreground">
              {formatDay(shown.date)}
              {hover === points.length - 1 ? ' (today)' : ''}
            </p>
            <p className="text-muted-foreground tabular-nums">
              Expected {formatValue(shown.low, metric)}–
              {formatValue(shown.high, metric)}
            </p>
          </div>
        ) : null}
      </div>
      <div
        aria-hidden
        className="flex justify-between text-xs text-muted-foreground"
      >
        <span>{formatDay(points[0].date)}</span>
        <span>Today</span>
      </div>
      {/* The same numbers for screen readers, which skip the drawing */}
      <table className="sr-only">
        <caption>{metric.name}, last 15 days</caption>
        <thead>
          <tr>
            <th>Day</th>
            <th>Actual</th>
            <th>Expected</th>
          </tr>
        </thead>
        <tbody>
          {points.map((p) => (
            <tr key={p.date}>
              <td>{formatDay(p.date)}</td>
              <td>{formatValue(p.actual, metric)}</td>
              <td>
                {formatValue(p.low, metric)} to {formatValue(p.high, metric)}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </figure>
  )
}

import { ArrowDown, ArrowUp, Check, ChevronRight } from 'lucide-react'
import type { ColumnDef, Table } from '@tanstack/react-table'

import { Badge } from '#/components/ui/badge'
import { Button } from '#/components/ui/button'
import { cn } from '#/lib/utils'
import {
  change,
  distance,
  formatChange,
  formatValue,
  kindOf,
  severity,
  verdict,
} from './anomalies'
import type { Metric } from './data'

export interface AnomalyMeta {
  /** Metric ids someone has marked as reviewed */
  reviewed: Set<string>
  toggleReviewed: (id: string) => void
}

const getMeta = (table: Table<Metric>) =>
  table.options.meta as unknown as AnomalyMeta

// Orange for above the range, violet for below: the same in the chart
export const kindStyle = {
  spike: {
    label: 'Spike',
    icon: ArrowUp,
    badge: 'border-orange-500/50 text-orange-700 dark:text-orange-400',
    dot: 'bg-orange-500',
  },
  drop: {
    label: 'Drop',
    icon: ArrowDown,
    badge: 'border-violet-500/50 text-violet-700 dark:text-violet-400',
    dot: 'bg-violet-500',
  },
}

/**
 * The expected range as a bar, with a dot where today's value landed.
 * The scale stretches to fit both, so a far-off value is still on screen.
 */
function RangeBar({ metric }: { metric: Metric }) {
  const { actual, low, high } = metric.today
  const kind = kindOf(metric.today)
  const lo = Math.min(low, actual)
  const hi = Math.max(high, actual)
  const span = hi - lo || 1
  const at = (v: number) => 4 + ((v - lo) / span) * 92
  return (
    <div className="flex min-w-36 flex-col gap-1">
      <div aria-hidden className="relative h-2">
        <span className="absolute inset-x-0 top-1/2 h-px -translate-y-1/2 bg-border" />
        <span
          className="absolute inset-y-0 rounded-full bg-muted-foreground/25"
          style={{ left: `${at(low)}%`, width: `${at(high) - at(low)}%` }}
        />
        <span
          className={cn(
            'absolute top-1/2 size-2.5 -translate-1/2 rounded-full ring-2 ring-background',
            kind === 'normal' ? 'bg-foreground' : kindStyle[kind].dot,
          )}
          style={{ left: `${at(actual)}%` }}
        />
      </div>
      <span className="text-xs text-muted-foreground tabular-nums">
        {formatValue(low, metric)}–{formatValue(high, metric)}
      </span>
    </div>
  )
}

export const columns: ColumnDef<Metric>[] = [
  {
    id: 'expand',
    header: () => <span className="sr-only">History</span>,
    cell: ({ row }) => (
      <Button
        variant="ghost"
        size="icon"
        className="size-7"
        aria-expanded={row.getIsExpanded()}
        aria-label={`${row.getIsExpanded() ? 'Hide' : 'Show'} history for ${row.original.name}`}
        onClick={row.getToggleExpandedHandler()}
      >
        <ChevronRight
          className={cn(
            'transition-transform motion-reduce:transition-none',
            row.getIsExpanded() && 'rotate-90',
          )}
        />
      </Button>
    ),
  },
  {
    id: 'metric',
    header: 'Metric',
    cell: ({ row }) => {
      const kind = kindOf(row.original.today)
      const style = kind === 'normal' ? null : kindStyle[kind]
      return (
        <div className="flex flex-col sm:min-w-36">
          <span className="font-medium">{row.original.name}</span>
          <span className="text-xs text-muted-foreground">
            {row.original.segment}
          </span>
          {/* On phones the Flag column is hidden; the flag shows here */}
          {style ? (
            <span
              className={cn(
                'flex items-center gap-1 text-xs sm:hidden',
                style.badge,
              )}
            >
              <style.icon className="size-3" />
              {style.label}, {severity(row.original.today)}
            </span>
          ) : null}
        </div>
      )
    },
  },
  {
    id: 'actual',
    header: () => <span className="block text-right">Today</span>,
    cell: ({ row }) => (
      <span className="block text-right font-medium tabular-nums">
        {formatValue(row.original.today.actual, row.original)}
      </span>
    ),
  },
  {
    id: 'range',
    header: 'Expected range',
    cell: ({ row }) => <RangeBar metric={row.original} />,
  },
  {
    id: 'change',
    // Sorted by how far outside the range, so the worst comes first
    accessorFn: (m) => distance(m.today),
    header: () => <span className="block text-right">vs expected</span>,
    cell: ({ row }) => {
      const m = row.original
      const kind = kindOf(m.today)
      return (
        <div className="flex flex-col items-end">
          <span className="tabular-nums">{formatChange(change(m.today))}</span>
          {kind === 'normal' ? null : (
            <span className="text-xs text-muted-foreground">{verdict(m)}</span>
          )}
        </div>
      )
    },
  },
  {
    id: 'kind',
    accessorFn: (m) => kindOf(m.today),
    header: 'Flag',
    cell: ({ row }) => {
      const kind = kindOf(row.original.today)
      if (kind === 'normal')
        return <span className="text-sm text-muted-foreground">In range</span>
      const style = kindStyle[kind]
      const Icon = style.icon
      return (
        <div className="flex flex-col items-start gap-0.5">
          <Badge variant="outline" className={cn('gap-1', style.badge)}>
            <Icon className="size-3" />
            {style.label}
          </Badge>
          <span className="text-xs text-muted-foreground capitalize">
            {severity(row.original.today)}
          </span>
        </div>
      )
    },
  },
  {
    id: 'review',
    header: () => <span className="sr-only">Review</span>,
    cell: ({ row, table }) => {
      const m = row.original
      if (kindOf(m.today) === 'normal') return null
      const meta = getMeta(table)
      const done = meta.reviewed.has(m.id)
      return (
        <div className="flex justify-end">
          <Button
            variant={done ? 'ghost' : 'outline'}
            size="sm"
            aria-pressed={done}
            aria-label={
              done
                ? `${m.name} reviewed. Mark as not reviewed`
                : `Mark ${m.name} reviewed`
            }
            onClick={() => meta.toggleReviewed(m.id)}
            className={cn(done && 'text-muted-foreground')}
          >
            {/* Icon only on phones, where the table has little room */}
            <Check className={cn(!done && 'sm:hidden')} />
            <span className="hidden sm:inline">
              {done ? 'Reviewed' : 'Mark reviewed'}
            </span>
          </Button>
        </div>
      )
    },
  },
]

import { Fragment, useEffect, useRef, useState } from 'react'
import {
  flexRender,
  getCoreRowModel,
  getExpandedRowModel,
  getSortedRowModel,
  useReactTable,
} from '@tanstack/react-table'
import type { ExpandedState, SortingState } from '@tanstack/react-table'

import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '#/components/ui/table'
import { cn } from '#/lib/utils'
import { context, formatDay, formatValue, kindOf } from './anomalies'
import { columns } from './columns'
import type { AnomalyMeta } from './columns'
import type { Metric } from './data'
import { HistoryChart } from './history-chart'

// Secondary columns step aside on small screens
const responsive: Record<string, string> = {
  range: 'hidden md:table-cell',
  change: 'hidden sm:table-cell',
  kind: 'hidden sm:table-cell',
  // The two button columns give up their inner padding on phones
  expand: 'pr-0 sm:pr-2',
  review: 'pl-0 sm:pl-2',
}

export function AnomalyTable({
  metrics,
  meta,
}: {
  /** Already filtered by the demo */
  metrics: Metric[]
  meta: AnomalyMeta
}) {
  const [sorting, setSorting] = useState<SortingState>([
    { id: 'change', desc: true },
  ])
  const [expanded, setExpanded] = useState<ExpandedState>({})
  const frame = useRef<HTMLDivElement>(null)
  const focusNext = useRef<string | null>(null)

  const table = useReactTable({
    data: metrics,
    columns,
    getRowId: (m) => m.id,
    // Every metric has a history to show
    getRowCanExpand: () => true,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getExpandedRowModel: getExpandedRowModel(),
    state: { sorting, expanded },
    onSortingChange: setSorting,
    onExpandedChange: setExpanded,
    meta: {
      ...meta,
      // When reviewed rows are hidden, the row leaves under the pointer:
      // remember the next one so focus can move there instead of vanishing
      toggleReviewed: (id) => {
        const ids = table.getRowModel().rows.map((r) => r.original.id)
        const i = ids.indexOf(id)
        focusNext.current = ids.at(i + 1) ?? ids.at(i - 1) ?? null
        meta.toggleReviewed(id)
      },
    } satisfies AnomalyMeta,
  })

  useEffect(() => {
    const id = focusNext.current
    if (!id) return
    focusNext.current = null
    // Only when the button that had focus is gone; otherwise to the next
    // row's review button, or its expand button if it's in range
    if (frame.current?.contains(document.activeElement)) return
    const row = frame.current?.querySelector(`[data-metric="${id}"]`)
    ;(
      row?.querySelector<HTMLElement>('[aria-pressed]') ??
      row?.querySelector<HTMLElement>('button')
    )?.focus()
  })

  const rows = table.getRowModel().rows

  return (
    <div ref={frame} className="overflow-hidden rounded-md border">
      <Table>
        <TableHeader>
          {table.getHeaderGroups().map((group) => (
            <TableRow key={group.id} className="hover:bg-transparent">
              {group.headers.map((header) => (
                <TableHead
                  key={header.id}
                  className={cn(
                    responsive[header.column.id],
                    header.column.id === 'expand' && 'w-10',
                  )}
                >
                  {flexRender(
                    header.column.columnDef.header,
                    header.getContext(),
                  )}
                </TableHead>
              ))}
            </TableRow>
          ))}
        </TableHeader>
        <TableBody>
          {rows.length ? (
            rows.map((row) => {
              const m = row.original
              const facts = context(m)
              return (
                <Fragment key={row.id}>
                  <TableRow
                    data-metric={m.id}
                    className={cn(
                      row.getIsExpanded() && 'border-b-0',
                      meta.reviewed.has(m.id) && 'text-muted-foreground',
                    )}
                  >
                    {row.getVisibleCells().map((cell) => (
                      <TableCell
                        key={cell.id}
                        className={responsive[cell.column.id]}
                      >
                        {flexRender(
                          cell.column.columnDef.cell,
                          cell.getContext(),
                        )}
                      </TableCell>
                    ))}
                  </TableRow>
                  {row.getIsExpanded() ? (
                    <TableRow className="bg-muted/30 hover:bg-muted/30">
                      <TableCell />
                      <TableCell colSpan={columns.length - 1} className="py-4">
                        <div className="grid gap-6 sm:grid-cols-[minmax(0,1fr)_14rem]">
                          <HistoryChart metric={m} />
                          <dl className="grid content-start gap-x-4 gap-y-2 text-sm">
                            <div>
                              <dt className="text-xs text-muted-foreground">
                                Expected today
                              </dt>
                              <dd className="tabular-nums">
                                {formatValue(m.today.low, m)}–
                                {formatValue(m.today.high, m)}
                              </dd>
                            </div>
                            <div>
                              <dt className="text-xs text-muted-foreground">
                                7-day average
                              </dt>
                              <dd className="tabular-nums">
                                {formatValue(facts.average7, m)}
                              </dd>
                            </div>
                            <div>
                              <dt className="text-xs text-muted-foreground">
                                Same day last week
                              </dt>
                              <dd className="tabular-nums">
                                {formatValue(facts.lastWeek.actual, m)}
                              </dd>
                            </div>
                            <div>
                              <dt className="text-xs text-muted-foreground">
                                Earlier days outside the range
                              </dt>
                              <dd>
                                {facts.outside.length
                                  ? facts.outside
                                      .map(
                                        (p) =>
                                          `${formatDay(p.date)} (${kindOf(p)})`,
                                      )
                                      .join(', ')
                                  : 'None in the last 14 days'}
                              </dd>
                            </div>
                          </dl>
                        </div>
                      </TableCell>
                    </TableRow>
                  ) : null}
                </Fragment>
              )
            })
          ) : (
            <TableRow className="hover:bg-transparent">
              <TableCell
                colSpan={columns.length}
                className="h-32 text-center text-muted-foreground"
              >
                Nothing to investigate here.
              </TableCell>
            </TableRow>
          )}
        </TableBody>
      </Table>
    </div>
  )
}

import { useMemo, useState } from 'react'
import { CheckCheck } from 'lucide-react'

import { Button } from '#/components/ui/button'
import { Label } from '#/components/ui/label'
import { Switch } from '#/components/ui/switch'
import { inView, kindOf, views } from './anomalies'
import type { View } from './anomalies'
import { metrics as businessMetrics } from './data'
import type { Metric } from './data'
import { AnomalyTable } from './data-table'

/**
 * The investigation view for any set of metrics. On its own it shows the
 * business example; the finance example passes its own numbers in.
 */
export function AnomalyInvestigationDemo({
  metrics = businessMetrics,
}: {
  metrics?: Metric[]
}) {
  const [view, setView] = useState<View>('anomalies')
  const [hideReviewed, setHideReviewed] = useState(false)
  const [reviewed, setReviewed] = useState<Set<string>>(new Set())

  const shown = useMemo(
    () =>
      metrics.filter(
        (m) => inView(m, view) && !(hideReviewed && reviewed.has(m.id)),
      ),
    [metrics, view, hideReviewed, reviewed],
  )

  const flagged = metrics.filter((m) => kindOf(m.today) !== 'normal')
  const open = flagged.filter((m) => !reviewed.has(m.id))
  const shownOpen = shown.filter(
    (m) => kindOf(m.today) !== 'normal' && !reviewed.has(m.id),
  )

  return (
    <div className="space-y-3">
      <div className="flex flex-wrap items-center justify-between gap-x-6 gap-y-3">
        <div
          role="group"
          aria-label="Show"
          className="inline-flex max-w-full overflow-x-auto rounded-md border p-0.5"
        >
          {views.map((v) => (
            <button
              key={v.id}
              type="button"
              aria-pressed={view === v.id}
              onClick={() => setView(v.id)}
              className="flex h-7 items-center gap-1.5 rounded px-2.5 text-sm whitespace-nowrap text-muted-foreground outline-none hover:text-foreground focus-visible:ring-[3px] focus-visible:ring-ring/50 aria-pressed:bg-muted aria-pressed:text-foreground"
            >
              {v.label}
              <span className="text-xs tabular-nums">
                {metrics.filter((m) => inView(m, v.id)).length}
              </span>
            </button>
          ))}
        </div>
        <div className="flex items-center gap-2">
          <Switch
            id="hide-reviewed"
            checked={hideReviewed}
            onCheckedChange={setHideReviewed}
          />
          <Label htmlFor="hide-reviewed" className="font-normal">
            Hide reviewed
          </Label>
        </div>
      </div>

      <AnomalyTable
        metrics={shown}
        meta={{
          reviewed,
          toggleReviewed: (id) =>
            setReviewed((r) => {
              const next = new Set(r)
              if (next.has(id)) next.delete(id)
              else next.add(id)
              return next
            }),
        }}
      />

      <div className="flex flex-wrap items-center justify-between gap-2 rounded-md bg-muted/50 px-3 py-1.5">
        <p aria-live="polite" className="text-sm text-muted-foreground">
          {open.length
            ? `${open.length} of ${flagged.length} anomalies left to review today.`
            : `All ${flagged.length} anomalies reviewed.`}
        </p>
        <Button
          variant="ghost"
          size="sm"
          disabled={!shownOpen.length}
          onClick={() =>
            setReviewed((r) => new Set([...r, ...shownOpen.map((m) => m.id)]))
          }
        >
          <CheckCheck />
          {shownOpen.length
            ? `Mark ${shownOpen.length} shown reviewed`
            : 'All shown reviewed'}
        </Button>
      </div>
    </div>
  )
}
